class Solution {
    public String minCostGoodCaption(String caption) {
        int n = caption.length();
        if (n < 3) {
            return "";
        }

        final int INF = (int) 1e9;
        int[] cost = new int[n + 1];
        int[] takeLen = new int[n + 1];
        char[] takeCh = new char[n + 1];

        cost[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (n - i < 3) {
                cost[i] = INF;
                continue;
            }

            int bestCost = INF;
            int bestL = 0;
            char bestC = 'a';

            for (int L = 3; L <= 5; L++) {
                if (i + L > n) {
                    continue;
                }

                int blockCost = INF;
                char blockCh = 'a';

                for (char ch = 'a'; ch <= 'z'; ch++) {
                    int currentCost = 0;
                    for (int k = i; k < i + L; k++) {
                        currentCost += Math.abs(caption.charAt(k) - ch);
                    }
                    if (currentCost < blockCost || (currentCost == blockCost && ch < blockCh)) {
                        blockCost = currentCost;
                        blockCh = ch;
                    }
                }

                if (cost[i + L] == INF) {
                    continue;
                }

                int candidate = blockCost + cost[i + L];
                if (candidate < bestCost || (candidate == bestCost && better(i, L, blockCh, bestL, bestC, takeLen, takeCh, n))) {
                    bestCost = candidate;
                    bestL = L;
                    bestC = blockCh;
                }
            }

            cost[i] = bestCost;
            takeLen[i] = bestL;
            takeCh[i] = bestC;
        }

        if (cost[0] == INF) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; ) {
            char ch = takeCh[i];
            int len = takeLen[i];
            for (int j = 0; j < len; j++) {
                result.append(ch);
            }
            i += len;
        }

        return result.toString();
    }

    private boolean better(int i, int L1, char c1, int L2, char c2, int[] takeLen, char[] takeCh, int n) {
        int p1 = i;
        int p2 = i;
        int r1 = L1;
        int r2 = L2;
        char a = c1;
        char b = c2;

        while (true) {
            if (a != b) {
                return a < b;
            }
            int step = Math.min(r1, r2);
            p1 += step;
            p2 += step;
            r1 -= step;
            r2 -= step;
            if (r1 == 0) {
                if (p1 == n) {
                    return false;
                }
                a = takeCh[p1];
                r1 = takeLen[p1];
            }
            if (r2 == 0) {
                if (p2 == n) {
                    return true;
                }
                b = takeCh[p2];
                r2 = takeLen[p2];
            }
        }
    }
}
